create or replace function gov_repo.ict_incident_classify_major(p_incident_id uuid)
returns table(is_major boolean,classification_basis text[],recommended_authority text,initial_notif_deadline timestamptz,intermediate_deadline timestamptz,final_deadline timestamptz,ai_act_reporting_required boolean,gdpr_notification_required boolean,dpa_deadline timestamptz)
language plpgsql security definer as $$ declare v_inc record;v_basis text[]:='{}';v_is_major boolean:=false;v_authority text;begin select * into v_inc from gov_repo.ict_incidents where incident_id=p_incident_id;if not found then raise exception 'Incident % not found',p_incident_id;end if;if v_inc.criterion_clients_affected then v_is_major:=true;v_basis:=v_basis||'EBA RTS Criterion: client threshold exceeded';end if;if v_inc.criterion_financial_threshold then v_is_major:=true;v_basis:=v_basis||'EBA RTS Criterion: financial impact threshold exceeded';end if;if v_inc.criterion_critical_service_down then v_is_major:=true;v_basis:=v_basis||'EBA RTS Criterion: critical ICT function unavailable > threshold';end if;if v_inc.criterion_reputational_impact then v_is_major:=true;v_basis:=v_basis||'EBA RTS Criterion: reputational impact assessed';end if;if v_inc.criterion_data_integrity_loss then v_is_major:=true;v_basis:=v_basis||'EBA RTS Criterion: data integrity or confidentiality loss';end if;if v_inc.criterion_duration_exceeded then v_is_major:=true;v_basis:=v_basis||'EBA RTS Criterion: duration threshold exceeded';end if;if v_inc.criterion_geographic_spread then v_is_major:=true;v_basis:=v_basis||'EBA RTS Criterion: geographic spread across regions';end if;if v_inc.severity='critical' then v_is_major:=true;v_basis:=v_basis||'Severity: critical — presumptive major incident';end if;v_authority:=case when v_inc.organisation_id is not null then 'Home NCA / ECB (SSM) — confirm with compliance' else 'Undetermined — consult legal' end;return query select v_is_major,v_basis,v_authority,case when v_is_major then now()+interval '4 hours' else null end,case when v_is_major then now()+interval '72 hours' else null end,case when v_is_major then now()+interval '1 month' else null end,(v_inc.involves_ai_system=true and v_inc.severity in ('critical','high')),v_inc.pii_data_exposed,case when v_inc.pii_data_exposed then coalesce(v_inc.detected_at,now())+interval '72 hours' else null end;end;$$;
create or replace function gov_repo.ict_dora_sla_status(p_organisation_id uuid)
returns table(incident_id uuid,incident_code varchar,title varchar,severity gov_repo.incident_severity,reporting_phase gov_repo.dora_reporting_phase,initial_notif_status text,initial_notif_minutes_left integer,intermediate_status text,intermediate_minutes_left integer,final_status text,final_minutes_left integer,overall_sla_status text,gdpr_status text,gdpr_minutes_left integer)
language sql security definer as $$ select i.incident_id,i.incident_code,i.title,i.severity,i.reporting_phase,case when i.initial_notification_sent_at is not null and i.initial_notification_sent_at<=i.initial_notification_deadline then 'submitted_on_time' when i.initial_notification_sent_at is not null and i.initial_notification_sent_at>i.initial_notification_deadline then 'submitted_late' when i.initial_notification_deadline<now() then 'overdue' when i.initial_notification_deadline is null then 'not_required' else 'pending' end,case when i.initial_notification_deadline is not null then extract(epoch from(i.initial_notification_deadline-now()))::integer/60 else null end,case when i.intermediate_report_sent_at is not null and i.intermediate_report_sent_at<=i.intermediate_report_deadline then 'submitted_on_time' when i.intermediate_report_sent_at is not null and i.intermediate_report_sent_at>i.intermediate_report_deadline then 'submitted_late' when i.intermediate_report_deadline is not null and i.intermediate_report_deadline<now() and i.intermediate_report_sent_at is null then 'overdue' when i.intermediate_report_deadline is null then 'not_required' else 'pending' end,case when i.intermediate_report_deadline is not null then extract(epoch from(i.intermediate_report_deadline-now()))::integer/60 else null end,case when i.final_report_sent_at is not null and i.final_report_sent_at<=i.final_report_deadline then 'submitted_on_time' when i.final_report_sent_at is not null and i.final_report_sent_at>i.final_report_deadline then 'submitted_late' when i.final_report_deadline is not null and i.final_report_deadline<now() and i.final_report_sent_at is null then 'overdue' when i.final_report_deadline is null then 'not_required' else 'pending' end,case when i.final_report_deadline is not null then extract(epoch from(i.final_report_deadline-now()))::integer/60 else null end,case when not i.is_major_incident then 'not_required' when(i.initial_notification_sent_at is null and i.initial_notification_deadline<now()) or(i.intermediate_report_sent_at is null and i.intermediate_report_deadline is not null and i.intermediate_report_deadline<now()) or(i.final_report_sent_at is null and i.final_report_deadline is not null and i.final_report_deadline<now()) then 'breach' when i.reporting_phase='all_complete' then 'compliant' else 'in_progress' end,case when not i.pii_data_exposed then 'not_required' when i.gdpr_breach_notified then 'notified' when i.dpa_notification_deadline<now() then 'overdue' else 'pending' end,case when i.dpa_notification_deadline is not null then extract(epoch from(i.dpa_notification_deadline-now()))::integer/60 else null end from gov_repo.ict_incidents i where i.organisation_id=p_organisation_id and i.is_major_incident=true and i.status not in ('closed') order by case when(i.initial_notification_sent_at is null and i.initial_notification_deadline<now()) then 1 else 2 end,i.initial_notification_deadline asc nulls last; $$;;
